class Solution {
  public int maxWeight(int n, int[][] edges, int k, int t) {
    int W = (t + 63) / 64;
    long[][] cur = new long[n][W];
    for (int v = 0; v < n; v++) cur[v][0] = 1;
    for (int step = 0; step < k; step++) {
      long[][] nxt = new long[n][W];
      for (int[] e : edges) {
        int u = e[0], v = e[1], w = e[2];
        int words = w / 64, bits = w % 64;
        for (int i = W - 1; i >= words; i--) {
          long x = cur[u][i - words] << bits;
          if (bits != 0 && i - words - 1 >= 0) x |= cur[u][i - words - 1] >>> (64 - bits);
          nxt[v][i] |= x;
        }
      }
      cur = nxt;
    }
    for (int w = t - 1; w >= 0; w--) {
      for (int v = 0; v < n; v++) if ((cur[v][w / 64] >>> (w % 64) & 1L) != 0) return w;
    }
    return -1;
  }
}
